            const agentTurn = event.update.kind === 'output' && next.agentTurn
                ? appendAssistantMessage(next.agentTurn, event.update)
                : next.agentTurn
            next = { ...next, agentTurn, logs: updateOutputLogs(next.logs, event, event.update) }
